"""knucker physical parameters: loads config/knucker_physics.yaml (generated by tools/export_physics.py from the
derivation in tools/derive.py). No tuning factors live here; every number is sourced in that file or in the catalog."""
import os

import yaml


def load_physics(path=None):
    if path is None:
        here = os.path.dirname(os.path.abspath(__file__))
        cands = [os.path.join(here, "..", "config", "knucker_physics.yaml")]
        try:
            from ament_index_python.packages import get_package_share_directory
            cands.append(os.path.join(get_package_share_directory("fleet_auv"), "config", "knucker_physics.yaml"))
        except Exception:
            pass
        path = next(p for p in cands if os.path.exists(p))
    with open(path) as f:
        return yaml.safe_load(f)
